// Toggl Track on an API token: every operation of the Track API v9, the Reports API v3 (with Insights) and the
// Webhooks API v1. actions.json is generated by `bun scripts/openapi-actions.ts toggl`; everything a workspace reports
// starts automations by webhook (triggers.ts).
import { z } from "zod";
import type { OwnApp } from "../index";
import { type Api, call, specActions } from "../openapi";
import { events, receive, triggers, unwatch, wanted, watch } from "./triggers";

export const api: Api = {
  name: "Toggl Track",
  base: "https://api.track.toggl.com/api/v9",
  tokenHelp: "track.toggl.com/profile → API Token",
  // HTTP basic auth: the token is the user name, the literal "api_token" the password
  auth: (key) => ({ Authorization: `Basic ${btoa(`${key}:api_token`)}` }),
  // Toggl answers a wrong token with a 403 "Incorrect username and/or password"; other 403s are a missing permission
  deadToken: (status, body) => status === 401 || (status === 403 && /incorrect username|password/i.test(JSON.stringify(body ?? ""))),
};

type Me = { id: number; fullname?: string; email?: string; api_token?: string } & Record<string, unknown>;
const ME = { method: "GET", path: "/me", query: ["with_related_data"], headers: [] };

const file = new URL("./actions.json", import.meta.url);
const actions = await specActions(file, api);

// Toggl wants the workspace in the body as well as the path (time entries, tasks...); the path's goes in when it's left out
for (const { name, input } of (await Bun.file(file).json()).actions as { name: string; input: { properties: Record<string, unknown> } }[]) {
  if (!("body_workspace_id" in input.properties)) continue;
  const action = actions[name]!;
  const run = action.run;
  action.run = (i: Record<string, unknown>, key) => run({ body_workspace_id: i.workspace_id, ...i }, key);
}

// Toggl wants every new time entry to say what made it, and a running timer to have duration -1
const create = actions.create_time_entry!;
const createRun = create.run;
create.run = (input: Record<string, unknown>, key) =>
  createRun({ created_with: "Emplio", ...(input.stop === undefined && input.duration === undefined && { duration: -1 }), ...input }, key);

export const toggl: OwnApp = {
  app: "toggl",
  name: "Toggl Track",
  logo: "/logos/toggl.svg",
  keyField: {
    label: "API token",
    help: "In Toggl Track open your profile (track.toggl.com/profile), scroll to API Token, click to reveal it and copy it. Emplio can then do whatever your Toggl Track account can.",
    placeholder: "a 32-character token",
  },
  async check(key) {
    const me = (await call(api, key, ME, {})) as Me;
    return me.fullname || me.email || String(me.id);
  },
  push: {
    events,
    triggers,
    start: (key, connection, event, config) => watch(api, key, connection, event, config),
    stop: (key, id) => unwatch(api, key, id),
    receive: (delivery) => receive(delivery),
    wanted,
  },
  actions: {
    ...actions,
    // the profile answer carries the API token itself; Emplio already has it and never needs to show it
    get_me: {
      description: "Who the connected Toggl Track account is: name, email, timezone, default workspace_id. Most calls need a workspace_id from here or from get_user_workspaces.",
      readOnly: true,
      input: z.object({ with_related_data: z.boolean().optional().describe("Also return the person's clients, projects, tags, tasks, time entries and workspaces") }),
      run: async (input: { with_related_data?: boolean }, key: string) => {
        const { api_token: _, ...me } = (await call(api, key, ME, input)) as Me;
        return me;
      },
    },
  },
};
